// Vectors generated by Go (scratchpad/p384/main.go) from go-credential-sdk key_material.go.
import {
  decodeECPublicMultibase, encodeP384PublicMultibase, jwkToHex, publicKeyHexFromVM, vmKeyKind,
} from '../../src/common/verification-method';
import { encodeBase58Btc } from '../../src/common/util/multibase';

const MB = 'z82Lkpc5WxSdJa9AEJ5XNxJFJuJfg13D1yJAWbxtdKL2uPH28V9D3KGFZkcxScQ1FbgxKax';
const HEX = '046f5f552c753d96bcd687200935e35b94f5b8a94bc2ae092267528367bedb1af2a8208a75a9249110d644186a24931801bc62fb0ee04c55aea2f1680a103a52eae3d34a99a7da6d32912974b3fe839df05eea504a816504226cb041faa9479e1c';
const X = 'b19VLHU9lrzWhyAJNeNblPW4qUvCrgkiZ1KDZ77bGvKoIIp1qSSRENZEGGokkxgB';
const Y = 'vGL7DuBMVa6i8WgKEDpS6uPTSpmn2m0ykSl0s_6DnfBe6lBKgWUEImywQfqpR54c';
const SHORT_X = 'TRBLJu5WcfcsEMmGhB0-ZdKF4lFhYbe6o0GxJjG54ytvDViW2EMcUdXZOjfLyQ4'; // 47 bytes
const SHORT_Y = '8RoeP4t7kFOO5CzADuk0puLuJVQWB9j7ZceosR4viGhTiG7vOGXskzIAufJVmfKf';
const SHORT_HEX = '04004d104b26ee5671f72c10c986841d3e65d285e2516161b7baa341b12631b9e32b6f0d5896d8431c51d5d93a37cbc90ef11a1e3f8b7b90538ee42cc00ee934a6e2ee25541607d8fb65c7a8b11e2f886853886eef3865ec933200b9f25599f29f';
const hex = (u: Uint8Array) => Buffer.from(u).toString('hex');

describe('P-384 (Go key_material.go parity)', () => {
  it('multikey decode matches Go', () => {
    const k = decodeECPublicMultibase(MB);
    expect(k.curve).toBe('P-384');
    expect(hex(k.uncompressed)).toBe(HEX);
  });
  it('multikey encode matches Go', () => {
    expect(encodeP384PublicMultibase(Buffer.from(HEX, 'hex'))).toBe(MB);
  });
  it('JWK decode matches Go, incl. left-padded short coordinate', () => {
    expect(jwkToHex({ kty: 'EC', crv: 'P-384', x: X, y: Y })).toBe(HEX);
    expect(jwkToHex({ kty: 'EC', crv: 'P-384', x: SHORT_X, y: SHORT_Y })).toBe(SHORT_HEX);
  });
  it('rejects like Go', () => {
    expect(() => jwkToHex({ kty: 'EC', crv: 'P-384', x: Buffer.alloc(49).toString('base64url'), y: 'AA' })).toThrow(/at most 48 bytes/);
    expect(() => jwkToHex({ kty: 'EC', crv: 'P-384', x: 'AQ', y: 'AQ' })).toThrow(/invalid public key point/);
    const bad = (n: number) => encodeBase58Btc(Uint8Array.from([0x81, 0x24, ...new Array(n).fill(0)]));
    expect(() => decodeECPublicMultibase(bad(49))).toThrow('invalid P-384 compressed point');
    expect(() => decodeECPublicMultibase(bad(33))).toThrow('invalid P-384 compressed point');
    expect(() => decodeECPublicMultibase(encodeBase58Btc(Uint8Array.from([0xe7, 0x01, 1, 2])))).toThrow(/unsupported multicodec prefix/);
  });
  it('publicKeyHexFromVM reads P-384 multikey; kind stays unrecognized as in Go', () => {
    const vm = { id: 'did:example:1#k', type: 'Multikey', controller: 'did:example:1', publicKeyMultibase: MB };
    expect(publicKeyHexFromVM(vm)).toBe(HEX);
    expect(vmKeyKind(vm)).toBeNull();
  });
});
